"use strict";
import ABSTRACT_ICON from "assets/wallets/abstract_icon.png";
import { RoundedLogo } from "components/Logo/LogoProvider";
import { CopyHelper } from "theme/components/CopyHelper";
import { Flex, Image, Text, styled, useSporeColors } from "ui/src";
import { shortenAddress } from "utilities/src/addresses";
const ProfileImage = styled(Image, {
  borderRadius: "$roundedFull",
  objectFit: "cover",
  variants: {
    size: {
      small: { width: 24, height: 24 },
      medium: { width: 32, height: 32 },
      large: { width: 40, height: 40 }
    }
  }
});
const FallbackAvatar = styled(Flex, {
  borderRadius: "$roundedFull",
  backgroundColor: "$neutral1",
  alignItems: "center",
  justifyContent: "center",
  variants: {
    size: {
      small: { width: 24, height: 24 },
      medium: { width: 32, height: 32 },
      large: { width: 40, height: 40 }
    }
  }
});
export default function UserProfileDisplay({
  address,
  profile,
  size = "large",
  showFullAddress = false,
  showCopyButton = true
}) {
  const displayAddress = showFullAddress ? address : shortenAddress(address);
  const displayName = profile?.name || shortenAddress(address);
  const hasProfileImage = profile?.profilePictureUrl && profile.profilePictureUrl !== "";
  const colors = useSporeColors();
  const iconSize = size === "small" ? 20 : size === "medium" ? 24 : 32;
  return <Flex row alignItems="center" gap="$spacing12">
      {
    /* Profile Image or Fallback */
  }
      {hasProfileImage ? <img
    style={{ borderRadius: "50%", objectFit: "cover" }}
    height={iconSize}
    width={iconSize}
    src={profile.profilePictureUrl}
    alt={`${displayName} profile`}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  /> : profile?.name || profile?.profilePictureUrl ? <Flex centered borderRadius={"$roundedFull"} height={iconSize} width={iconSize} overflow="hidden">
          <img src={ABSTRACT_ICON} height={iconSize + 4} width={iconSize + 4} alt="Abstract Icon" />
        </Flex> : <RoundedLogo color={colors.surface1.val} size={iconSize} />}

      {
    /* Profile Info */
  }
      <Flex flexDirection="column" gap="$spacing4">
        <Flex row alignItems="center" gap="$spacing8">
          <Text
    variant="body3"
    fontWeight={"$medium"}
    whiteSpace="nowrap"
    overflow="hidden"
    textOverflow="ellipsis"
    maxWidth={100}
  >
            {displayName}
          </Text>
          {
    /* {profile?.tier && (
      <ProfileText type="tier" size={size}>
        {profile.tier}
      </ProfileText>
    )} */
  }
        </Flex>

        {showCopyButton ? <CopyHelper visibleIcon color="$neutral2" iconSize={12} iconPosition="right" toCopy={address}>
            <Text variant="body3" color={"$neutral2"}>
              {displayAddress}
            </Text>
          </CopyHelper> : <Text variant="body3" color={"$neutral2"}>
            {displayAddress}
          </Text>}
      </Flex>
    </Flex>;
}
export function CompactUserProfile({ address, profile }) {
  return <UserProfileDisplay
    address={address}
    profile={profile}
    size="medium"
    showFullAddress={false}
    showCopyButton={true}
  />;
}
export function EnhancedUserProfile({ address, profile }) {
  return <Flex flexDirection="column" gap="$spacing8" flex={1}>
      <UserProfileDisplay
    address={address}
    profile={profile}
    size="large"
    showFullAddress={false}
    showCopyButton={true}
  />
      {profile?.description && <Text variant="body4" color="$neutral2" numberOfLines={2}>
          {profile.description}
        </Text>}
    </Flex>;
}
